// Extract Instagram posts data from HTML
const html = $input.all()[0].json.body;
const username = $input.all()[0].json.username;
const lastCheckDate = $input.all()[0].json.last_check || new Date(Date.now() - 24*60*60*1000).toISOString();

// Regex to find JSON data in Instagram page
const scriptRegex = /<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi;
const matches = [...html.matchAll(scriptRegex)];

let posts = [];
let newPosts = [];

for (const match of matches) {
  try {
    const jsonData = JSON.parse(match[1]);
    if (jsonData['@type'] === 'SocialMediaPosting') {
      const postDate = new Date(jsonData.datePublished);
      const checkDate = new Date(lastCheckDate);

      if (postDate > checkDate) {
        newPosts.push({
          username: username,
          platform: 'instagram',
          content: jsonData.headline || jsonData.text || 'No content available',
          url: jsonData.url,
          date: jsonData.datePublished,
          image: jsonData.image ? jsonData.image.url : null
        });
      }
    }
  } catch (e) {
    console.log('Error parsing JSON:', e);
  }
}

// Alternative method: parse from window._sharedData
const sharedDataRegex = /window\._sharedData = ({.*?});/;
const sharedDataMatch = html.match(sharedDataRegex);

if (sharedDataMatch && newPosts.length === 0) {
  try {
    const sharedData = JSON.parse(sharedDataMatch[1]);
    const userPosts = sharedData?.entry_data?.ProfilePage?.[0]?.graphql?.user?.edge_owner_to_timeline_media?.edges || [];

    for (const edge of userPosts.slice(0, 5)) { // Check last 5 posts
      const post = edge.node;
      const postDate = new Date(post.taken_at_timestamp * 1000);
      const checkDate = new Date(lastCheckDate);

      if (postDate > checkDate) {
        newPosts.push({
          username: username,
          platform: 'instagram',
          content: post.edge_media_to_caption?.edges?.[0]?.node?.text || 'No caption',
          url: `https://www.instagram.com/p/${post.shortcode}/`,
          date: postDate.toISOString(),
          image: post.display_url
        });
      }
    }
  } catch (e) {
    console.log('Error parsing shared data:', e);
  }
}

return newPosts.map(post => ({ json: post }));

// Extract Facebook posts data from HTML
const html = $input.all()[0].json.body;
const username = $input.all()[0].json.username;
const lastCheckDate = $input.all()[0].json.last_check || new Date(Date.now() - 24*60*60*1000).toISOString();

let newPosts = [];

// Try to find structured data
const scriptRegex = /<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi;
const matches = [...html.matchAll(scriptRegex)];

for (const match of matches) {
  try {
    const jsonData = JSON.parse(match[1]);
    if (jsonData['@type'] === 'SocialMediaPosting' || jsonData['@type'] === 'Article') {
      const postDate = new Date(jsonData.datePublished || jsonData.dateModified);
      const checkDate = new Date(lastCheckDate);

      if (postDate > checkDate) {
        newPosts.push({
          username: username,
          platform: 'facebook',
          content: jsonData.headline || jsonData.text || jsonData.description || 'No content available',
          url: jsonData.url || `https://www.facebook.com/${username}`,
          date: jsonData.datePublished || jsonData.dateModified,
          image: jsonData.image ? (typeof jsonData.image === 'string' ? jsonData.image : jsonData.image.url) : null
        });
      }
    }
  } catch (e) {
    console.log('Error parsing JSON:', e);
  }
}

// Alternative: Look for Open Graph meta tags for recent posts
if (newPosts.length === 0) {
  const titleMatch = html.match(/<meta property="og:title" content="([^"]*)"/i);
  const descMatch = html.match(/<meta property="og:description" content="([^"]*)"/i);
  const urlMatch = html.match(/<meta property="og:url" content="([^"]*)"/i);
  const imageMatch = html.match(/<meta property="og:image" content="([^"]*)"/i);

  if (titleMatch || descMatch) {
    // This is a basic fallback - in real scenario you'd need more sophisticated parsing
    newPosts.push({
      username: username,
      platform: 'facebook',
      content: descMatch ? descMatch[1] : (titleMatch ? titleMatch[1] : 'New post detected'),
      url: urlMatch ? urlMatch[1] : `https://www.facebook.com/${username}`,
      date: new Date().toISOString(),
      image: imageMatch ? imageMatch[1] : null
    });
  }
}

return newPosts.map(post => ({ json: post }));

// Format email content for new posts
const posts = $input.all();

if (posts.length === 0) {
  return [{ json: { skip: true } }];
}

let emailContent = `
<h2>🔔 Новые публикации конкурентов</h2>
<p>Обнаружены новые публикации за последние 24 часа:</p>
`;

for (const item of posts) {
  const post = item.json;
  emailContent += `
  <div style="border: 1px solid #ddd; padding: 15px; margin: 10px 0; border-radius: 5px;">
    <h3>📱 ${post.platform.toUpperCase()}: @${post.username}</h3>
    <p><strong>Дата:</strong> ${new Date(post.date).toLocaleString('ru-RU')}</p>
    <p><strong>Содержание:</strong></p>
    <blockquote style="background: #f5f5f5; padding: 10px; border-left: 3px solid #007cba;">
      ${post.content.substring(0, 500)}${post.content.length > 500 ? '...' : ''}
    </blockquote>
    <p><a href="${post.url}" target="_blank" style="color: #007cba;">🔗 Посмотреть публикацию</a></p>
    ${post.image ? `<p><img src="${post.image}" style="max-width: 300px; height: auto;" alt="Post image"></p>` : ''}
  </div>
  `;
}

emailContent += `
<hr>
<p><small>Автоматическое уведомление от системы мониторинга конкурентов</small></p>
`;

return [{
  json: {
    subject: `🔔 Обнаружено ${posts.length} новых публикаций конкурентов`,
    html: emailContent,
    text: posts.map(item => `${item.json.platform.toUpperCase()}: @${item.json.username} - ${item.json.content.substring(0, 200)}...`).join('\n\n')
  }
}];
